changeSet.sql:
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'tickets') AND name = N'checked_in')
    ALTER TABLE tickets ADD checked_in bit NOT NULL DEFAULT 0;
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'tickets') AND name = N'checked_in_at')
    ALTER TABLE tickets ADD checked_in_at datetime2 NULL;

rollback.sql:
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'tickets') AND name = N'checked_in_at')
    ALTER TABLE tickets DROP COLUMN checked_in_at;
IF EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'tickets') AND name = N'checked_in')
    ALTER TABLE tickets DROP COLUMN checked_in;
